int z_impl_k_work_submit_to_queue(struct k_work_q *queue, struct k_work *work)
{
	int ret;
	unsigned int key = irq_lock();

	if (work->flags & K_WORK_QUEUED) {
		ret = 0;
	} else if (work->flags & K_WORK_RUNNING) {
		/* Work is currently running. Re-queue it to the same queue
		 * it is running on.
		 */
		__ASSERT_NO_MSG(queue == work->queue);
		ret = 2;
	} else if (queue->flags & K_WORK_QUEUE_PLUGGED) {
		ret = -EBUSY;
	} else {
		work->flags |= K_WORK_QUEUED;
		work->queue = queue;
		k_work_q_insert(queue, work);
		ret = 1;
	}

	irq_unlock(key);
	return ret;
}

